  return obj;
});
const poisData=poisRows.slice(1).map(r=>{
  const obj={};
  poisHeader.forEach((h,i)=>{obj[h]=r[i];});
  return obj;
});
const outRows=[['qid','label','poi_type','nearest_stop_id','nearest_stop_name','distance_m']];
for(const poi of poisData){
  let minDist=Infinity;
